// Put the implementation in a struct so we don't pollute the top-level namespace
fileprivate struct UniffiCallbackInterfacePermissionProvider {

    // Create the VTable using a series of closures.
    // Swift automatically converts these into C callback functions.
    //
    // Store the vtable directly.
    static let vtable: UniffiVTableCallbackInterfacePermissionProvider = UniffiVTableCallbackInterfacePermissionProvider(
        uniffiFree: { (uniffiHandle: UInt64) -> () in
            do {
                try FfiConverterTypePermissionProvider.handleMap.remove(handle: uniffiHandle)
            } catch {
                print("Uniffi callback interface PermissionProvider: handle missing in uniffiFree")
            }
        },
        uniffiClone: { (uniffiHandle: UInt64) -> UInt64 in
            do {
                return try FfiConverterTypePermissionProvider.handleMap.clone(handle: uniffiHandle)
            } catch {
                fatalError("Uniffi callback interface PermissionProvider: handle missing in uniffiClone")
            }
        },
        status: { (
            uniffiHandle: UInt64,
            permission: RustBuffer,
            uniffiFutureCallback: @escaping UniffiForeignFutureCompleteRustBuffer,
            uniffiCallbackData: UInt64,
            uniffiOutDroppedCallback: UnsafeMutablePointer<UniffiForeignFutureDroppedCallbackStruct>
        ) in
            let makeCall = {
                () async throws -> PermissionStatus in
                guard let uniffiObj = try? FfiConverterTypePermissionProvider.handleMap.get(handle: uniffiHandle) else {
                    throw UniffiInternalError.unexpectedStaleHandle
                }
                return await uniffiObj.status(
                     permission: try FfiConverterTypeNativePermission_lift(permission)
                )
            }

            let uniffiHandleSuccess = { (returnValue: PermissionStatus) in
                uniffiFutureCallback(
                    uniffiCallbackData,
                    UniffiForeignFutureResultRustBuffer(
                        returnValue: FfiConverterTypePermissionStatus_lower(returnValue),
                        callStatus: RustCallStatus()
                    )
                )
            }
            let uniffiHandleError = { (statusCode, errorBuf) in
                uniffiFutureCallback(
                    uniffiCallbackData,
                    UniffiForeignFutureResultRustBuffer(
                        returnValue: RustBuffer.empty(),
                        callStatus: RustCallStatus(code: statusCode, errorBuf: errorBuf)
                    )
                )
            }
            uniffiTraitInterfaceCallAsync(
                makeCall: makeCall,
                handleSuccess: uniffiHandleSuccess,
                handleError: uniffiHandleError,
                droppedCallback: uniffiOutDroppedCallback
            )
        },
        request: { (
            uniffiHandle: UInt64,
            permission: RustBuffer,
            uniffiFutureCallback: @escaping UniffiForeignFutureCompleteRustBuffer,
            uniffiCallbackData: UInt64,
            uniffiOutDroppedCallback: UnsafeMutablePointer<UniffiForeignFutureDroppedCallbackStruct>
        ) in
            let makeCall = {
                () async throws -> PermissionStatus in
                guard let uniffiObj = try? FfiConverterTypePermissionProvider.handleMap.get(handle: uniffiHandle) else {
                    throw UniffiInternalError.unexpectedStaleHandle
                }
                return await uniffiObj.request(
                     permission: try FfiConverterTypeNativePermission_lift(permission)
                )
            }

            let uniffiHandleSuccess = { (returnValue: PermissionStatus) in
                uniffiFutureCallback(
                    uniffiCallbackData,
                    UniffiForeignFutureResultRustBuffer(
                        returnValue: FfiConverterTypePermissionStatus_lower(returnValue),
                        callStatus: RustCallStatus()
                    )
                )
            }
            let uniffiHandleError = { (statusCode, errorBuf) in
                uniffiFutureCallback(
                    uniffiCallbackData,
                    UniffiForeignFutureResultRustBuffer(
                        returnValue: RustBuffer.empty(),
                        callStatus: RustCallStatus(code: statusCode, errorBuf: errorBuf)
                    )
                )
            }
            uniffiTraitInterfaceCallAsync(
                makeCall: makeCall,
                handleSuccess: uniffiHandleSuccess,
                handleError: uniffiHandleError,
                droppedCallback: uniffiOutDroppedCallback
            )
        }
    )

    // Rust stores this pointer for future callback invocations, so it must live
    // for the process lifetime (not just for the init function call).
    //
    // `nonisolated(unsafe)` is needed under Swift 6 strict concurrency.
    // This is safe because the pointee is initialized once during static init
    // and never mutated by either side of the FFI.  Its fields are C function pointers.
    nonisolated(unsafe) static let vtablePtr: UnsafePointer<UniffiVTableCallbackInterfacePermissionProvider> = {
        let ptr = UnsafeMutablePointer<UniffiVTableCallbackInterfacePermissionProvider>.allocate(capacity: 1)
        ptr.initialize(to: vtable)
        return UnsafePointer(ptr)
    }()
}

private func uniffiCallbackInitPermissionProvider() {
    uniffi_relay_core_fn_init_callback_vtable_permissionprovider(UniffiCallbackInterfacePermissionProvider.vtablePtr)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypePermissionProvider: FfiConverter {
    fileprivate static let handleMap = UniffiHandleMap<PermissionProvider>()

    typealias FfiType = UInt64
    typealias SwiftType = PermissionProvider

    public static func lift(_ handle: UInt64) throws -> PermissionProvider {
        if ((handle & 1) == 0) {
            // Rust-generated handle, construct a new class that uses the handle to implement the
            // interface
            return PermissionProviderImpl(unsafeFromHandle: handle)
        } else {
            // Swift-generated handle, get the object from the handle map
            return try handleMap.remove(handle: handle)
        }
    }

    public static func lower(_ value: PermissionProvider) -> UInt64 {
         if let rustImpl = value as? PermissionProviderImpl {
             // Rust-implemented object.  Clone the handle and return it
            return rustImpl.uniffiCloneHandle()
         } else {
            // Swift object, generate a new vtable handle and return that.
            return handleMap.insert(obj: value)
         }
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> PermissionProvider {
        let handle: UInt64 = try readInt(&buf)
        return try lift(handle)
    }

    public static func write(_ value: PermissionProvider, into buf: inout [UInt8]) {
        writeInt(&buf, lower(value))
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypePermissionProvider_lift(_ handle: UInt64) throws -> PermissionProvider {
    return try FfiConverterTypePermissionProvider.lift(handle)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypePermissionProvider_lower(_ value: PermissionProvider) -> UInt64 {
    return FfiConverterTypePermissionProvider.lower(value)
}






/**
 * The app's core. The Swift app opens one per process and shares it.
 */
public protocol RelayCoreProtocol: AnyObject, Sendable {
    
    /**
     * The host's background time ran out: finishing work stops.
     */
    func backgroundTimeExpired() 
    
    /**
     * Whether commands or finishing work are still running; the
     * host holds background time while they are.
     */
    func backgroundWorkPending()  -> Bool
    
    /**
     * Stops the receive in progress, if any; it ends with an error, and
     * what arrived stays for a resume.
     */
    func cancelCodeReceive() 
    
    /**
     * Stops the send in progress, if any.
     */
    func cancelCodeSend() 
    
    /**
     * Stops a send to a trusted device that is still going, or takes it
     * off the outbox if it is waiting.
     */
    func cancelTransfer(id: UInt64) 
    
    /**
     * The size of the file being received with a code, and how much of it
     * was already here from an earlier try; `None` when none is running or
     * the sender hasn't named the file yet.
     */
    func codeReceiveSize()  -> CodeSize?
    
    /**
     * The other senders the app sees advertising nearby, replacing the last
     * list. A new code avoids their numbers, and if one takes this code's
     * number before it is used, the code is replaced.
     */
    func codeSendNearby(senders: [NearbySender]) 
    
    /**
     * Where the send with a code has got.
     */
    func codeSendStatus()  -> CodeSend
    
    /**
     * Which routes trusted devices are reached by.
     */
    func connectionMode()  -> ConnectionMode
    
    /**
     * Tries every trusted device something waits for, now: Relay came
     * back to the foreground. (Seeing a device, or it connecting here,
     * tries it too; so does a timer while Relay is open.)
     */
    func deliverWaiting() 
    
    /**
     * Starts this device on iroh, if it isn't yet, so trusted devices can
     * reach it. The app advertises the result with Bonjour while Relay is
     * on screen.
     */
    func deviceService() async throws  -> DeviceService
    
    /**
     * Asks a trusted device what it says about itself (its platform and
     * what it offers), and remembers the answer and when it came. Tried
     * where the resolver says (`dial`), within the connection mode. Returns
     * the device as `devices` lists it.
     */
    func deviceStatus(endpointId: String) async throws  -> Device
    
    /**
     * Trusted and revoked devices, by name. Forgotten ones aren't listed.
     */
    func devices()  -> [Device]
    
    /**
     * The trusted devices the app sees nearby now, replacing the last list.
     * A device that appears, or moves, is tried at once if something
     * waits for it.
     */
    func devicesNearby(devices: [NearbyDevice]) 
    
    /**
     * The person has read the notice.
     */
    func dismissSavedDataNotice() async throws 
    
    /**
     * The person said Not Now to the offer `trust_offer` gave.
     */
    func dismissTrustOffer() 
    
    /**
     * The runtime's event stream: `Changed { revision }` after each
     * committed command, phase changes, and drops. Nil after shutdown.
     */
    func events()  -> RuntimeEvents?
    
    /**
     * Takes the device off the list. Pair Automatically may trust it
     * again after a code transfer; a revoked device stays revoked.
     */
    func forgetDevice(endpointId: String) async throws 
    
    /**
     * This device, as others see it.
     */
    func identity()  -> Identity
    
    /**
     * What the runtime found at open (unfinished background work).
     */
    func launchReport()  -> LaunchReport
    
    /**
     * The network changed (another Wi-Fi, Wi-Fi to mobile data): Relay
     * looks for its routes again and tries what waits.
     */
    func networkChanged() 
    
    func pairingPolicy()  -> PairingPolicy
    
    /**
     * The phase last reported.
     */
    func phase()  -> AppPhase
    
    /**
     * Saves what later code receives bring into `folder` (made if missing)
     * instead of Relay's own `codes/received`. The app passes a folder in
     * its Documents so received files show in the Files app; what was
     * received before stays where it is, and stays in the history.
     */
    func receiveInto(folder: String) throws 
    
    /**
     * Receives the file or folder a sender offers with a word code such as
     * `37-grasp-gag-drum` (Relay M1; the sender is another Relay or
     * `relay send`). `addresses` and `endpoint_id` come from the
     * sender's Bonjour advertisement (`CODE_SERVICE_TYPE`, TXT `n` = the
     * code's number, `id` = the endpoint id). Every chunk is verified, and
     * it is saved in the folder [`RelayCore::receive_into`] chose (the app
     * passes Documents/Relay), or Relay's own `codes/received` if none was
     * chosen; several items arrive as one folder. A dropped receive
     * resumes with the sender's next code, also after a relaunch. Once the
     * sender has named what it sends, the receive goes into the history.
     * One at a time.
     */
    func receiveWithCode(code: String, addresses: [String], endpointId: String) async throws  -> CodeReceipt
    
    /**
     * Removes a history entry and, for a received file, the file.
     */
    func removeTransfer(id: UInt64) async throws 
    
    func renameDevice(name: String) async throws 
    
    /**
     * The last committed revision.
     */
    func revision()  -> UInt64
    
    /**
     * Ends trust in the device: its trusted connections are refused, and
     * no policy or code makes it trusted again by itself. One-off code
     * transfers still work, as with any device.
     */
    func revokeDevice(endpointId: String) async throws 
    
    /**
     * What Relay couldn't read of its saved data when it opened, and
     * where that is kept, for the app to show until the person dismisses
     * it. `None` normally.
     */
    func savedDataNotice()  -> SavedDataNotice?
    
    /**
     * Starts sending several files and folders as one transfer with a new
     * word code, like `send_with_code`. The receiver gets them in one
     * folder named "N items"; two items with the same name are refused.
     */
    func sendPathsWithCode(paths: [String]) throws 
    
    /**
     * Sends files and folders to a trusted device as one transfer, with
     * no code. Several items arrive in one folder named "N items". They
     * are copied into Relay's store first, so they can wait in the outbox
     * (and the originals can go); as for a note, the transfer comes back
     * Done, or Waiting.
     */
    func sendToDevice(endpointId: String, paths: [String]) async throws  -> Transfer
    
    /**
     * Starts sending the file or folder at `path` with a new word code, in
     * the background (Relay M1). Follow it with `code_send_status`: while it
     * has a code, the app advertises it with Bonjour and reports other
     * senders it sees with `code_send_nearby`. The receiver is another
     * Relay, or `relay-spike receive <code>` for a file. When it ends it
     * goes into the history. One at a time.
     */
    func sendWithCode(path: String) throws 
    
    /**
     * Relay's own servers: a relay and a lookup server (M2 PR 7).
     */
    func servers()  -> RelayServers
    
    /**
     * Only Hybrid uses the relay server. Leaving Hybrid lets go of the
     * relay at once, and any connection that still finds a relay path is
     * refused; Relay opens without the relay from then on. Coming back to
     * Hybrid takes the relay up again (fully from the next open, when
     * Relay opened outside Hybrid).
     */
    func setConnectionMode(mode: ConnectionMode) async throws 
    
    /**
     * Whether a trusted device may ask this device's AI. Off when a
     * device is trusted; trust never turns it on.
     */
    func setMayAsk(endpointId: String, on: Bool) async throws 
    
    func setPairingPolicy(policy: PairingPolicy) async throws 
    
    /**
     * The host reports the application lifecycle phase.
     */
    func setPhase(phase: AppPhase) 
    
    /**
     * Whether a trusted device may send files and notes here.
     */
    func setReceivesFrom(endpointId: String, on: Bool) async throws 
    
    /**
     * Sets Relay's servers. They are used from the next time Relay opens.
     */
    func setServers(servers: RelayServers) async throws 
    
    /**
     * Refuses new commands, stops work in flight and ends event
     * streams. Commands already accepted still finish and save.
     */
    func shutdown() 
    
    /**
     * Everything sent and received, newest first, with progress for what
     * is still going. Never waits for a command.
     */
    func transfers()  -> [Transfer]
    
    /**
     * The person trusts the device: from the trust offer, or a revoked
     * device trusted again from the list. The only way a revoked device
     * becomes trusted again.
     */
    func trustDevice(endpointId: String) async throws 
    
    /**
     * The oldest device a code transfer was with that the pairing policy
     * asks whether to trust. Ask on both sides; each decides for itself.
     * Once it is answered, the next one (if any) is offered.
     */
    func trustOffer()  -> TrustOffer?
    
}
