#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeRelayCore: FfiConverter {
    typealias FfiType = UInt64
    typealias SwiftType = RelayCore

    public static func lift(_ handle: UInt64) throws -> RelayCore {
        return RelayCore(unsafeFromHandle: handle)
    }

    public static func lower(_ value: RelayCore) -> UInt64 {
        return value.uniffiCloneHandle()
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> RelayCore {
        let handle: UInt64 = try readInt(&buf)
        return try lift(handle)
    }

    public static func write(_ value: RelayCore, into buf: inout [UInt8]) {
        writeInt(&buf, lower(value))
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeRelayCore_lift(_ handle: UInt64) throws -> RelayCore {
    return try FfiConverterTypeRelayCore.lift(handle)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeRelayCore_lower(_ value: RelayCore) -> UInt64 {
    return FfiConverterTypeRelayCore.lower(value)
}






/**
 * Secrets (tokens, keys, passwords), stored by the platform's
 * secure store: the iOS Keychain, readable after the first
 * unlock and never synced or restored to another device.
 * Survives app updates; on iOS it can survive deleting the app.
 */
public protocol SecureStore: AnyObject, Sendable {
    
    /**
     * The value stored under `key`, or `None`.
     */
    func get(key: String) throws  -> Data?
    
    /**
     * Stores `value` under `key`, replacing any old value.
     */
    func set(key: String, value: Data) throws 
    
    /**
     * Removes `key`. Removing a missing key is not an error.
     */
    func delete(key: String) throws 
    
}
/**
 * Secrets (tokens, keys, passwords), stored by the platform's
 * secure store: the iOS Keychain, readable after the first
 * unlock and never synced or restored to another device.
 * Survives app updates; on iOS it can survive deleting the app.
 */
open class SecureStoreImpl: SecureStore, @unchecked Sendable {
    fileprivate let handle: UInt64

    /// Used to instantiate a [FFIObject] without an actual handle, for fakes in tests, mostly.
#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    public struct NoHandle {
        public init() {}
    }

    // TODO: We'd like this to be `private` but for Swifty reasons,
    // we can't implement `FfiConverter` without making this `required` and we can't
    // make it `required` without making it `public`.
#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    required public init(unsafeFromHandle handle: UInt64) {
        self.handle = handle
    }

    // This constructor can be used to instantiate a fake object.
    // - Parameter noHandle: Placeholder value so we can have a constructor separate from the default empty one that may be implemented for classes extending [FFIObject].
    //
    // - Warning:
    //     Any object instantiated with this constructor cannot be passed to an actual Rust-backed object. Since there isn't a backing handle the FFI lower functions will crash.
#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    public init(noHandle: NoHandle) {
        self.handle = 0
    }

#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    public func uniffiCloneHandle() -> UInt64 {
        return try! rustCall { uniffi_relay_core_fn_clone_securestore(self.handle, $0) }
    }
    // No primary constructor declared for this class.

    deinit {
        if handle == 0 {
            // Mock objects have handle=0 don't try to free them
            return
        }

        try! rustCall { uniffi_relay_core_fn_free_securestore(handle, $0) }
    }

    

    
